-- ============================================================================
-- Seed: "BC Calendar" automation profile (filters, steps, and actions).
-- Extracted from the database; automation runs are intentionally excluded.
-- Idempotent: every insert uses ON CONFLICT (id) DO NOTHING.
-- Guarded: skips cleanly when the prerequisite lookup data is absent (admin user id 3),
--          so it never breaks a fresh DB.
-- The LLM is environment-specific (it holds an api_key) and is NOT seeded; the
-- profile links to it by name when that LLM exists. Report/notification
-- references resolve to NULL when they do not exist in the target database.
-- ============================================================================
DO $seed$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "user" WHERE id = 3) THEN
    RAISE NOTICE 'Skipping "BC Calendar" seed: prerequisite data not present.';
    RETURN;
  END IF;

  -- Filters (owned by admin user id 3)
INSERT INTO filter (id,owner_id,query,settings,created_by,created_on,updated_by,updated_on,version,name,description,is_enabled,sort_order) VALUES ('19','3','{"size": 50, "sort": [{"publishedOn": "desc"}], "query": {"bool": {"must": [{"terms": {"sourceId": [174]}}, {"query_string": {"query": "\"The Canadian Press News Agenda for\"", "fields": ["headline^5"], "phrase_slop": 0, "analyze_wildcard": true, "fuzzy_prefix_length": 0, "fuzzy_max_expansions": 50, "fuzzy_transpositions": true, "allow_leading_wildcard": true, "max_determinized_states": 1000, "enable_position_increments": true, "auto_generate_synonyms_phrase_query": true}}], "filter": [{"range": {"publishedOn": {"gte": "now/d", "time_zone": "US/Pacific"}}}], "must_not": [{"terms": {"mediaTypeId": [10]}}]}}}','{"from": 0, "size": 50, "tags": [], "search": "\"The Canadian Press News Agenda for\"", "actions": [], "inStory": false, "inByline": false, "queryType": "query-string", "sentiment": [], "seriesIds": [], "sourceIds": [174], "dateOffset": 0, "inHeadline": true, "contentTypes": [], "mediaTypeIds": [], "contributorIds": [], "sourceIdsNegate": false, "searchUnpublished": true}','admin','2026-07-29T17:36:25.213525+00:00','admin','2026-07-30T19:03:31.607945+00:00','1','BC Calendar','Find the Calendar story from the Canadian Press so that the BC events can be extracted.','true','0') ON CONFLICT (id) DO NOTHING;

  -- Profile (LLM linked by name when present, otherwise left null)
INSERT INTO automation_profile (id,schema_version,filter_id,llm_id,created_by,created_on,updated_by,updated_on,version,name,description,is_enabled,sort_order) VALUES ('3','1','19',(SELECT id FROM llm WHERE name='automation  profiles' LIMIT 1),'admin','2026-07-31T22:37:42.873069+00:00','admin','2026-07-31T22:37:42.873069+00:00','0','BC Calendar','','true','0') ON CONFLICT (id) DO NOTHING;

  -- Steps
INSERT INTO automation_step (id,automation_profile_id,prompt,target,filter_id,apply_to_automation_filter,created_by,created_on,updated_by,updated_on,version,name,description,is_enabled,sort_order,iterate_step_filter,llm_id,send_separate_prompts,use_chat_completions) VALUES ('11','3','<p>## Role</p><p>You are an experienced news editor for the Media Monitoring Insights (MMI) service. You review news stories and decide which editorial actions should be performed on each story.</p><p><br></p><p>## Instructions</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Review the news story in the News Story section below.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Evaluate each action in the Actions section against the story.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Only confirm an action when its criteria are clearly met by the story.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>For each action you confirm, respond with that action''s exact confirmation statement on its own line.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>If an action should not be performed, do not output its confirmation statement.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Do not output anything else - no explanations, no formatting, no additional commentary.</li></ol><p><br></p><p>## News Story Schema</p><p>The news story is a JSON document from Elasticsearch with the following notable fields:</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>id (number): unique identifier of the content item.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>status (string): workflow status; "Published" means visible to subscribers.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>contentType (string): the kind of content ("AudioVideo", "PrintContent", "Image", "Story").</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>source (object): the publisher/outlet of the story. Fields: name (e.g. "Vancouver Sun"), code (unique source code, e.g. "SUN"), shortName. otherSource (string) holds the source code when no source record is linked.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>mediaType (object): the media category (e.g. Daily Print, Talk Radio, Online).</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>series (object): the show/program, column, or publication series the story belongs to, when applicable. Fields: name; isOther indicates an ad-hoc series. otherSeries (string) holds a series name when no series record is linked.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>contributor (object): the columnist/pundit, when applicable.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>headline (string): the story headline.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>byline (string): the author(s).</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>edition (string), section (string), page (string): print placement details.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>summary (string): the editor-written summary; may be empty.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>body (string): the full story text; may be empty for some media types.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>publishedOn (date-time): when the source published the story.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>postedOn (date-time): when the story was added to MMI.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>isHidden (boolean), isApproved (boolean), isPrivate (boolean): visibility and workflow flags.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>actions (array): editorial actions already applied to this story. Each item has: name (e.g. "Featured Story", "Top Story", "Commentary", "Alert"), value (the assigned value; may be empty), valueLabel and valueType (how to interpret value). The presence of an item means that action has already been applied - do not confirm an action that is already applied.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>topics (array): event-of-the-day topics assigned to the story. Each item has: name, score (importance score), topicType ("Issues" or "Proactive").</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>tags (array): tags assigned to the story. Each item has: code (short unique code) and name.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>labels (array): key/value labels extracted or assigned.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>tonePools (array): sentiment ratings for the story. Each item has: name (the rater/tone pool) and value (integer from -5 very negative to +5 very positive; 0 is neutral).</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>quotes (array): notable quotes extracted from the story. Each item has: statement (the quoted text) and byline (who said it).</li></ol><p><br></p><p>## News Story</p><p>Here is the news story you will review:</p><p>{content}</p>','content',NULL,'false','admin','2026-07-31T22:37:42.873057+00:00','admin','2026-07-31T22:37:42.873057+00:00','0','find and create','','true','0','false',NULL,'true','false') ON CONFLICT (id) DO NOTHING;

  -- Actions
INSERT INTO automation_action (id,name,automation_step_id,prompt,action_type,max_calls,confirmation_statement,content_field,content_action_id,is_enabled,sort_order,created_by,created_on,updated_by,updated_on,version,objective,report_id,notification_id,prior_action_id,auto_execute,llm_id,abort_if_no_confirmation,works_on,create_identifier,create_clone,settings) VALUES ('650','calendar','11','','extract-data',NULL,'',NULL,NULL,'true','0','admin','2026-07-31T22:37:42.873065+00:00','admin','2026-07-31T23:33:29.65166+00:00','16',NULL,NULL,NULL,NULL,'false',NULL,'false',NULL,NULL,'false','{"extract": [{"key": "headline", "value": "\"BC Calendar\""}, {"key": "byline", "value": "{content.byline}"}, {"key": "summary", "value": "{content.summary}"}, {"key": "body", "value": "Parse the {content.body} and return the section for British Columbia news events.  Include this section with its title."}, {"key": "edition", "value": "{content.edition}"}, {"key": "section", "value": "{content.section}"}, {"key": "page", "value": "{content.page}"}, {"key": "status", "value": "{content.status}"}, {"key": "contentType", "value": "{content.contentType}"}, {"key": "source", "value": "{content.sourceId}"}, {"key": "mediaType", "value": "{content.mediaTypeId}"}, {"key": "series", "value": "{content.seriesId}"}, {"key": "tags", "value": "{content.tags}"}, {"key": "topics", "value": "{content.topics}"}, {"key": "sentiment", "value": "{content.sentiment}"}]}') ON CONFLICT (id) DO NOTHING;
INSERT INTO automation_action (id,name,automation_step_id,prompt,action_type,max_calls,confirmation_statement,content_field,content_action_id,is_enabled,sort_order,created_by,created_on,updated_by,updated_on,version,objective,report_id,notification_id,prior_action_id,auto_execute,llm_id,abort_if_no_confirmation,works_on,create_identifier,create_clone,settings) VALUES ('651','create','11','','create-content',NULL,'',NULL,NULL,'true','1','admin','2026-07-31T22:37:42.873065+00:00','admin','2026-07-31T23:33:29.65166+00:00','16',NULL,NULL,NULL,NULL,'false',NULL,'false',NULL,'calendar','true','{"mapping": {"body": "body", "page": "page", "tags": "tags", "byline": "byline", "series": "series", "source": "source", "status": "status", "topics": "topics", "edition": "edition", "section": "section", "summary": "summary", "headline": "headline", "mediaType": "mediaType", "sentiment": "sentiment", "contentType": "contentType"}}') ON CONFLICT (id) DO NOTHING;
INSERT INTO automation_action (id,name,automation_step_id,prompt,action_type,max_calls,confirmation_statement,content_field,content_action_id,is_enabled,sort_order,created_by,created_on,updated_by,updated_on,version,objective,report_id,notification_id,prior_action_id,auto_execute,llm_id,abort_if_no_confirmation,works_on,create_identifier,create_clone,settings) VALUES ('652','sentiment','11','<p>Review the `content.headline`, `content.summary`, and `content.body` and generate a sentiment value from -5 to 5, where -5 is negative sentiment and 5 is positive sentiment. Base your evaluation on the perspective of the BC Government viewpoint. Respond with the following "[SENTIMENT:{value}]" where {value} is the sentiment value.</p>','add-sentiment',NULL,'[SENTIMENT:{value}]',NULL,NULL,'true','2','admin','2026-07-31T22:37:42.873066+00:00','admin','2026-07-31T23:33:29.651661+00:00','16',NULL,NULL,NULL,NULL,'false',NULL,'false','calendar',NULL,'false','{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO automation_action (id,name,automation_step_id,prompt,action_type,max_calls,confirmation_statement,content_field,content_action_id,is_enabled,sort_order,created_by,created_on,updated_by,updated_on,version,objective,report_id,notification_id,prior_action_id,auto_execute,llm_id,abort_if_no_confirmation,works_on,create_identifier,create_clone,settings) VALUES ('653','tags','11','<p>Review the `content.headline`, `content.summary`, and `content.body` and determine which tags apply to this story. Respond with "[TAGS:{value}]" where {value} is a comma-separated list of tag codes.</p>','add-tags',NULL,'[TAGS:{value}]',NULL,NULL,'true','3','admin','2026-07-31T22:37:42.873067+00:00','admin','2026-07-31T23:33:29.651662+00:00','16',NULL,NULL,NULL,NULL,'false',NULL,'false','calendar',NULL,'false','{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO automation_action (id,name,automation_step_id,prompt,action_type,max_calls,confirmation_statement,content_field,content_action_id,is_enabled,sort_order,created_by,created_on,updated_by,updated_on,version,objective,report_id,notification_id,prior_action_id,auto_execute,llm_id,abort_if_no_confirmation,works_on,create_identifier,create_clone,settings) VALUES ('654','format','11','<p>Review the `content.body` field and do the following to the value:</p><ol><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>Surround each event with a &lt;p&gt;&lt;/p&gt; tag. There should be an extra line between each event.</li><li data-list="bullet"><span class="ql-ui" contenteditable="false"></span>At bottom write out all "{content.tags}" in square brackets, use lowercase (i.e. "[gdx, trans]").</li></ol><p>Respond with the new value wrapped in markers exactly as follows:</p><p>[UPDATE FIELD START:body]</p><p>{value}</p><p>[UPDATE FIELD END:body]</p><p>Where {value} is the complete new value for the field.</p>','update-content-field',NULL,'[UPDATE FIELD START:body]
{value}
[UPDATE FIELD END:body]','body',NULL,'true','4','admin','2026-07-31T22:37:42.873067+00:00','admin','2026-07-31T23:33:29.651662+00:00','19',NULL,NULL,NULL,NULL,'false',NULL,'false','calendar',NULL,'false','{}') ON CONFLICT (id) DO NOTHING;
INSERT INTO automation_action (id,name,automation_step_id,prompt,action_type,max_calls,confirmation_statement,content_field,content_action_id,is_enabled,sort_order,created_by,created_on,updated_by,updated_on,version,objective,report_id,notification_id,prior_action_id,auto_execute,llm_id,abort_if_no_confirmation,works_on,create_identifier,create_clone,settings) VALUES ('655','publish','11','<p>Respond with "[PUBLISH CONTENT]".</p>','publish-content',NULL,'[PUBLISH CONTENT]',NULL,NULL,'true','5','admin','2026-07-31T22:37:42.873068+00:00','admin','2026-07-31T23:33:29.651663+00:00','17',NULL,NULL,NULL,NULL,'true',NULL,'false','calendar',NULL,'false','{}') ON CONFLICT (id) DO NOTHING;

  -- Advance identity sequences past the seeded ids so future inserts don't collide.
  PERFORM setval(pg_get_serial_sequence('filter', 'id'), GREATEST((SELECT max(id) FROM filter), 1));
  PERFORM setval(pg_get_serial_sequence('automation_profile', 'id'), GREATEST((SELECT max(id) FROM automation_profile), 1));
  PERFORM setval(pg_get_serial_sequence('automation_step', 'id'), GREATEST((SELECT max(id) FROM automation_step), 1));
  PERFORM setval(pg_get_serial_sequence('automation_action', 'id'), GREATEST((SELECT max(id) FROM automation_action), 1));

  RAISE NOTICE 'Seeded "BC Calendar" automation profile.';
END
$seed$;
